          "用户名用于识别公开账号。只输入用户名，能够确认的是对方获知了要指向哪个账号。除此之外是否有授权，要由账号所有者看平台授权记录。TikTok 授权范围文档说明，不同授权范围可以读取特定资料或允许执行特定动作，使用者可以同意、拒绝或撤销授权。看到授权页面时，应记下应用名称、具体权限和同意时间。品牌的原生广告授权也应单独登记，并核对 TikTok 广告授权生命周期里的素材和有效期，避免把正规投放与陌生工具混为一谈。\n\n密码、验证码或会话令牌另行处理。只要有人在陌生表单提交其中一项，安全负责人就可按暴露流程接手，即使粉丝曲线平稳。原生应用里看不到陌生连接，也无法排除凭证被钓鱼。遇到无权查看的信息时，让账号所有者或经授权的管理员核实。品牌能从负责人那里得到带时间的确认即可，不需要收集完整的账号权限面板。",
          "A handle identifies a public account. If the team only supplied a handle, the confirmed fact is that the recipient learned which account was involved. To determine whether access was granted, have the account owner inspect the platform’s own authorization records. TikTok’s scopes documentation explains how particular grants allow access to specified data or actions, and how users can deny or revoke authorization. Record the app name, the permissions shown and the approval time when that information is available. Keep official advertising access in a separate row. A TikTok ad authorization lifecycle record helps identify legitimate creator content and expiry windows before an unfamiliar grant is investigated.\n\nTreat credentials, verification codes and session tokens separately from app permissions. Entering one into an unfamiliar form is sufficient reason for the security owner to start exposure response, even when follower counts stayed steady. An empty connected-app list cannot rule out a phishing event. The owner can identify unfamiliar sign-ins without giving a marketing coordinator control over the account. Record the permission state as granted, revoked, unknown or not observed in the reviewed interface, with a timestamp and the reviewer’s role. That level of detail gives the brand a way to follow up while keeping the decision with the person who has appropriate access."
