          "Put public observations, native follower changes, publication times and paid delivery on a common timeline. For each row, record when the data was collected, the reporting time zone and the dates the report covers. Two public snapshots establish a span in which a change was observed. An abbreviated profile count cannot establish an exact daily increment. Where native data provides the breakdown, track gains, losses and net change separately. Preserve the original units and mark periods whose reporting is still settling.\n\nThen test explanations against that same window. Did the brand start an ad using creator content? Did a livestream, a recommended clip or a reshare from another creator drive viewers to the profile? Check paid delivery records and creative IDs alongside content reach, profile visits, substantive comments and later engagement. Those metrics can arrive at different times and describe different populations. Matching them by date, asset and event type prevents a false contradiction from taking over the review. Use a consistent creator engagement reading method to establish a comparable baseline. Three recent posts in the same format by the same creator may give the team more useful questions than an average from unrelated accounts. The comparison is a starting point for explanation; it cannot individually certify followers."
