          "Suppose a creator sees 2,100 net new followers on Tuesday. The paid team verifies that an ad went live that day, and the creator supplies a new video URL. The ad’s delivery window overlaps part of the rise. Those are verifiable events. Attributing the whole change to them is still an interpretation. Ask for the organic and paid delivery scopes, definitions of profile visits and follows, and details of other promotion. If the available screenshot covers Monday through Wednesday as one total, label attribution unresolved. Specify the missing breakdown, its owner and when it can be supplied.\n\nRepeated sharp increases, stable profile visits despite a large reported gain, generic repeated comments, or a revised export that no longer matches its original can all be worth examining. Each has plausible alternatives. Referrals from outside the platform may go unrecorded. A regional event can concentrate search demand. An agency could merge the wrong report windows or pick up a prior export by mistake. Confirmed findings cite their own source. A verified invoice or message may establish a purchase, while delivery, the amount affected and the specific accounts involved need separate support. Put the threshold for expanding access, increasing fees or making any public statement above the threshold for requesting routine clarification."
