          "Check whether any part of payment actually depends on follower growth. Video production, publication, usage rights and delivery of a tracking link often have their own acceptance evidence. Review those items against the agreed requirements. For a follower-based bonus whose period, definition or origin is disputed, retain the original report and route that line to the person authorized to apply the contract. A handoff with three columns works well: verified deliverables, unattributed growth and access issues still in response. Avoid carrying a provisional label into a public creator record.\n\nIn the U.S., the FTC’s consumer reviews rule Q&A describes specific conditions for misuse of fake social influence indicators under the U.S. rule, including commercial purpose and what a party knew or should have known. Applying a rule or contract to particular facts belongs with the relevant compliance or contractual owner. The campaign team can immediately make future quoting more reliable by requiring native evidence where available, separating organic and paid scope, defining eligible delivery before launch and requiring account-owner approval for third-party access. Close the current review with a next check date and a named owner for each open item. If evidence remains incomplete, preserve that limit when deciding whether to expand the next brief or pay a performance component."
