          "Guinness’s Instagram follower record lists Cristiano Ronaldo at 621,979,902 followers on February 19, 2024. Describe it as a dated Guinness record. Keep it outside the current snapshot column, and avoid using it to guarantee that today’s order cannot change. The two sources have different dates, comparison sets and precision. Store both observations separately unless you explicitly intend to compare a period and have checked their definitions. Put the observation date next to the claim. A headline does not need to promise a live leaderboard.\n\nKeep the handle, profile URL, original displayed value, observation time and source name. If the original reads 681M, communicate it as an approximation. Writing 681,000,000 as an exact measured count suggests access to precision the source did not supply. When two abbreviated values are close, the visible figures may be inadequate to establish their order. Group the candidates into a scale band and check the information that could change the brief, such as reach from relevant language content. If the material will be reused next month, put a refresh date on the record and identify which fields need to be checked again."
