          "Keep the target sales market separate from follower geography. A city shown in a post or a language listed in a bio cannot replace audience data. Ask the creator for aggregate evidence they are authorized to share, and label whether the data describes followers, viewers or accounts reached. If the launch covers two countries, ask whether a small test is possible in those markets with the proposed language and format. A missing aggregate field does not justify requesting individual follower records.\n\nWhen a screenshot has no visible window, ask a direct question: “Does this show accounts reached in the past 30 days, or the current follower breakdown?” After the owner answers, use the evidence only in that scope. When a market slice is unavailable, a localized script or a collaboration with a local creator can be part of a follow-up test. Neither provides the missing reach measurement. An evidence-status column helps the team decide whether to request a native sample, run a pilot, or compare a different candidate without inventing a precise local ranking from a global follower total."
