          "The brand may find an agent’s address through a public bio. If the proposed deliverable requires publication on the main account, ask the contact to confirm the account represented, content deliverable, contracting entity and approver. A team can manage several related accounts. Put the exact account and any co-publication option on the quote. Confirm who can publish, which regions are available for promotion and who controls original assets before negotiating on scale. A professional-looking profile link does not authenticate later payment instructions or an unexpected change of address.\n\nCheck where earlier partnerships actually appeared. A celebrity might feature prominently in a video published by the brand. When the current brief requires creator-side distribution, establish whether it means a main-account post, a co-published asset or permission for the brand to run the footage. Each may fit a different objective and require a different fee and evidence. An old sample demonstrates an appearance in that asset. It does not commit a particular publishing account for the new campaign. Keep that distinction in the contract confirmation field until the authorized owner responds."
