          "Give the creator button, brand destination sessions and target outcome separate columns. Clicks can repeat. Sessions follow the destination analytics rules and may depend on browser behavior, consent and page loading. Orders can use another attribution period and can change with return or validation status. Align time zone and window, and keep the collection source and time. Use a creator destination attribution process to distinguish directly attributable actions from observations in the same period. A shared label such as conversion does not establish the same event in two systems.\n\nSuppose the button shows 100 clicks, brand reporting records 72 tagged sessions, and the order system confirms six eligible orders. Report the three values independently. The difference does not establish that 28 people abandoned the journey. The six orders cannot automatically be assigned to one creator post unless the evidence supports it. Use diagnostic fields for repeat clicking, exits, lost parameters, window differences and missing access. Update the explanation when evidence arrives rather than forcing the systems to agree by adjusting a count."
